<script lang="ts">import type { Snippet } from 'svelte';let { count = 0, rowH = 28, overscan = 8, children }: { count?: number; rowH?: number; overscan?: number; children?: Snippet<[number]> } = $props();let el = $state<HTMLDivElement | null>(null);let scrollTop = $state(0);let h = $derived(el?.clientHeight ?? 400);let start = $derived(Math.max(0, Math.floor(scrollTop / rowH) - overscan));let end = $derived(Math.min(count, Math.ceil((scrollTop + h) / rowH) + overscan));let visible = $derived(Array.from({ length: Math.max(0, end - start) }, (_, i) => start + i));</script><div class="vl" bind:this={el} onscroll={() => { if (el) scrollTop = el.scrollTop; }}><div style={`height:${count * rowH}px;position:relative`}><div style={`transform:translateY(${start * rowH}px)`}>{#each visible as idx}<div style={`height:${rowH}px`}>{#if children}{@render children(idx)}{/if}</div>{/each}</div></div></div><style>.vl{overflow:auto;position:relative}.vl>div{width:100%}</style>
